//
// Filter a structural variant VCF with SURVIVOR and/or bcftools
//

include { BCFTOOLS_FILTER                                   } from 'nf-core/bcftools/filter'
include { HTSLIB_BGZIPTABIX as HTSLIB_BGZIPTABIX_DECOMPRESS } from 'nf-core/htslib/bgziptabix'
include { HTSLIB_BGZIPTABIX as HTSLIB_BGZIPTABIX_COMPRESS   } from 'nf-core/htslib/bgziptabix'
include { SURVIVOR_FILTER                                   } from 'nf-core/survivor/filter'

// Please note that this subworkflow requires the options for SURVIVOR_FILTER defined in the nextflow.config of this directory
workflow VCF_FILTER_SURVIVOR_BCFTOOLS {

    take:
    ch_vcf           // channel: [ val(meta), path(vcf), path(bed) ] - pass [] for bed to filter genome-wide
    minsv            //   value: min SV size (-1 to disable)
    maxsv            //   value: max SV size (-1 to disable)
    minallelefreq    //   value: min allele frequency (0-1)
    minnumreads      //   value: min number of reads supporting the SV (-1 to disable)
    val_tools_to_use //   value: a list of tools to use, options are: ["survivor", "bcftools"]

    main:
    def allowed_tools = ['survivor', 'bcftools']
    if (!(val_tools_to_use instanceof Collection) || val_tools_to_use.isEmpty() || !val_tools_to_use.every { tool -> tool in allowed_tools }) {
        error("VCF_FILTER_SURVIVOR_BCFTOOLS: `val_tools_to_use` must be a list of one or more of ${allowed_tools.join(', ')}, got: ${val_tools_to_use}")
    }

    def ch_filtered_vcf = ch_vcf.map { meta, vcf, _bed -> [meta, vcf] }

    // SURVIVOR can only read uncompressed VCFs
    if ('survivor' in val_tools_to_use) {
        HTSLIB_BGZIPTABIX_DECOMPRESS(
            ch_vcf.map { meta, vcf, _bed -> [meta, vcf, [], []] },
            'decompress',
            false,
            'vcf',
        )

        SURVIVOR_FILTER(
            HTSLIB_BGZIPTABIX_DECOMPRESS.out.output
                .join(ch_vcf.map { meta, _vcf, bed -> [meta, bed] }, failOnDuplicate: true, failOnMismatch: true),
            minsv,
            maxsv,
            minallelefreq,
            minnumreads,
        )

        ch_filtered_vcf = SURVIVOR_FILTER.out.vcf
    }

    // Filter expressions can be passed to bcftools filter with ext.args, e.g. '-e "QUAL<20"'
    if ('bcftools' in val_tools_to_use) {
        BCFTOOLS_FILTER(
            ch_filtered_vcf.map { meta, vcf -> [meta, vcf, []] },
        )

        ch_filtered_vcf = BCFTOOLS_FILTER.out.vcf
    }

    HTSLIB_BGZIPTABIX_COMPRESS(
        ch_filtered_vcf.map { meta, vcf -> [meta, vcf, [], []] },
        'compress',
        true,
        'vcf',
    )

    ch_vcf_tbi = HTSLIB_BGZIPTABIX_COMPRESS.out.output.join(HTSLIB_BGZIPTABIX_COMPRESS.out.index, failOnDuplicate: true, failOnMismatch: true)

    emit:
    vcf     = HTSLIB_BGZIPTABIX_COMPRESS.out.output // channel: [ val(meta), path(vcf.gz) ]
    tbi     = HTSLIB_BGZIPTABIX_COMPRESS.out.index  // channel: [ val(meta), path(tbi) ]
    vcf_tbi = ch_vcf_tbi                            // channel: [ val(meta), path(vcf.gz), path(tbi) ]
}

// IMPORTANT: This config file should be included to ensure that the subworkflow works properly.
process {
    withName: '.*VCF_FILTER_SURVIVOR_BCFTOOLS:SURVIVOR_FILTER' {
        ext.prefix = { "${meta.id}.survivor" }
    }
    withName: '.*VCF_FILTER_SURVIVOR_BCFTOOLS:BCFTOOLS_FILTER' {
        ext.prefix = { "${meta.id}.bcftools" }
    }
}

nextflow_workflow {

    name "Test Subworkflow VCF_FILTER_SURVIVOR_BCFTOOLS"
    script "../main.nf"
    workflow "VCF_FILTER_SURVIVOR_BCFTOOLS"
    config "./nextflow.config"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/vcf_filter_survivor_bcftools"
    tag "bcftools"
    tag "bcftools/filter"
    tag "htslib"
    tag "htslib/bgziptabix"
    tag "survivor"
    tag "survivor/filter"

    test("homo sapiens - sv vcf gz - survivor bcftools") {

        when {
            workflow {
                """
                input[0] = channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/sv_query.vcf.gz', checkIfExists: true),
                    []
                ])
                input[1] = 1000
                input[2] = -1
                input[3] = 0
                input[4] = -1
                input[5] = [ 'survivor', 'bcftools' ]
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    file(workflow.out.tbi[0][1]).name,
                    path(workflow.out.vcf[0][1]).vcf.variantsMD5,
                    path(workflow.out.vcf[0][1]).vcf.summary,
                ).match() }
            )
        }
    }

    test("homo sapiens - sv vcf - survivor") {

        when {
            workflow {
                """
                input[0] = channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/gridss.somatic.vcf', checkIfExists: true),
                    []
                ])
                input[1] = 1000
                input[2] = -1
                input[3] = 0
                input[4] = -1
                input[5] = [ 'survivor' ]
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    file(workflow.out.tbi[0][1]).name,
                    path(workflow.out.vcf[0][1]).vcf.variantsMD5,
                    path(workflow.out.vcf[0][1]).vcf.summary,
                ).match() }
            )
        }
    }

    test("homo sapiens - sv vcf gz - bcftools") {

        when {
            workflow {
                """
                input[0] = channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/sv_query.vcf.gz', checkIfExists: true),
                    []
                ])
                input[1] = -1
                input[2] = -1
                input[3] = 0
                input[4] = -1
                input[5] = [ 'bcftools' ]
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    file(workflow.out.tbi[0][1]).name,
                    path(workflow.out.vcf[0][1]).vcf.variantsMD5,
                    path(workflow.out.vcf[0][1]).vcf.summary,
                ).match() }
            )
        }
    }

    test("homo sapiens - sv vcf gz - bed - survivor bcftools") {

        when {
            workflow {
                """
                input[0] = channel.of('chr22\t16000000\t17500000')
                    .collectFile(name: 'regions.bed', newLine: true)
                    .map { bed -> [
                        [ id:'test' ], // meta map
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/sv_query.vcf.gz', checkIfExists: true),
                        bed
                    ] }
                input[1] = 1000
                input[2] = -1
                input[3] = 0
                input[4] = -1
                input[5] = [ 'survivor', 'bcftools' ]
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    file(workflow.out.tbi[0][1]).name,
                    path(workflow.out.vcf[0][1]).vcf.variantsMD5,
                    path(workflow.out.vcf[0][1]).vcf.summary,
                ).match() }
            )
        }
    }

    test("homo sapiens - sv vcf gz - survivor bcftools - stub") {

        options "-stub"

        when {
            workflow {
                """
                input[0] = channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/vcf/sv_query.vcf.gz', checkIfExists: true),
                    []
                ])
                input[1] = 1000
                input[2] = -1
                input[3] = 0
                input[4] = -1
                input[5] = [ 'survivor', 'bcftools' ]
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(workflow.out).match() }
            )
        }
    }
}

